import hashlib, json
from pathlib import Path
base = Path('products/services/sqlite-repair')
inbound = base / 'bespoke-inbound'
handoff = base / 'original-fixture/verified-handoff'
draft = inbound / 'director-operator-reply-draft.md'
control = inbound / 'fictional-reply-control.json'
expected = {draft: '7be71b7c2a2aca12c30bf966e64de904cd8586382dcbeefca1fc6b6478cd17da', control: 'a7d0641f0552c9c27a1d824b3c278137aa5a885b45486937167edb21736c558a'}
def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
report_fields = {'status', 'rows', 'actual_rows', 'expected_rows', 'expected_match', 'statement_count', 'query_statement_count', 'executed_statement_count', 'tail', 'tail_sql', 'unexecuted_tail', 'open_statements', 'close_rc', 'finalized_statements', 'cleanup'}
def observations(value, prefix=''):
    if isinstance(value, dict):
        for key, child in value.items():
            name = '.'.join(filter(None, (prefix, key)))
            if key in report_fields:
                yield name, child
            if isinstance(child, (dict, list)):
                yield from observations(child, name)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from observations(child, f'{prefix}[{index}]')
files = sorted(path for path in handoff.rglob('*') if path.is_file())
assert files and all(digest(path) == sha for path, sha in expected.items())
result = {'draft_and_control_hashes_verified': {str(path): sha for path, sha in expected.items()}, 'handoff_files': {str(path): digest(path) for path in files}, 'observed_json_fields': {str(path): dict(observations(json.loads(path.read_text(encoding='utf-8')))) for path in files if path.suffix == '.json'}, 'scope': 'Committed fictional evidence only. Extracted fields require comparison with both reports and the draft before operator handoff.'}
output = inbound / 'operator-evidence-crosswalk.json'
output.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
assert json.loads(output.read_text(encoding='utf-8')) == result
print(output, digest(output))
